const crypto = require('crypto');
const item = $input.first();
let raw;
if (item.binary?.data) raw = await this.helpers.getBinaryDataBuffer(0, 'data');
else if (typeof item.json.rawBody === 'string') raw = Buffer.from(item.json.rawBody, 'utf8');
else if (typeof item.json.body === 'string') raw = Buffer.from(item.json.body, 'utf8');
else raw = Buffer.from(JSON.stringify(item.json.body ?? {}), 'utf8');
const rawBody = raw.toString('utf8');
let parsedPayload = null;
try { parsedPayload = JSON.parse(rawBody); } catch {}
const headers = item.json.headers ?? {};
const allow = ['content-type','user-agent','x-bling-signature-256','x-signature','x-shopee-signature','x-request-id','x-signature-version','x-signature-ts'];
const safeHeaders = {};
for (const key of allow) if (headers[key] !== undefined) safeHeaders[key] = String(headers[key]).slice(0, 2048);
const payload = parsedPayload ?? (typeof item.json.body === 'object' ? item.json.body : null);
return [{ json: { schema_version: 1, event_id: crypto.randomUUID(), source: 'bling', received_at: new Date().toISOString(), headers: safeHeaders, raw_body: rawBody, parsed_payload: payload, body_sha256: crypto.createHash('sha256').update(raw).digest('hex'), provider_delivery_id: payload?.eventId ?? payload?.id ?? headers['x-request-id'] ?? null, payload_size: raw.length, oversized: raw.length > 1048576 } }];

const envelope = $('Build Durable Envelope').first().json;
const data = Buffer.from(JSON.stringify(envelope), 'utf8');
return [{ json: envelope, binary: { data: { data: data.toString('base64'), mimeType: 'application/json', fileName: envelope.event_id + '.json' } } }];

const crypto = require('crypto');

// O Bling assina o corpo cru com o client_secret do APLICATIVO, e temos um
// aplicativo por conta. Nao da para saber a conta antes de validar, entao
// testamos todos os segredos.
let SECRETS = [];
try {
  const parsed = JSON.parse($env.BLING_CLIENT_SECRETS || '[]');
  if (Array.isArray(parsed)) {
    // Descarta placeholder e valor curto: uma lista nao-vazia sem segredo real
    // e pior que lista vazia, porque transforma erro de configuracao em
    // "assinatura invalida" e derruba todo o ingest.
    SECRETS = parsed.map((s) => String(s ?? '').trim()).filter((s) => s.length >= 8 && s !== '...');
  }
} catch (e) {
  SECRETS = [];
}

// Enquanto false, o veredito e apenas calculado e anexado; nada e bloqueado.
// Promova para 'true' apos confirmar signature_valid numa execucao real.
const ENFORCE = String($env.BLING_SIGNATURE_ENFORCE ?? 'false').trim().toLowerCase() === 'true';

const item = $input.first();
let raw;
if (item.binary?.data) raw = await this.helpers.getBinaryDataBuffer(0, 'data');
else if (typeof item.json.rawBody === 'string') raw = Buffer.from(item.json.rawBody, 'utf8');
else if (typeof item.json.body === 'string') raw = Buffer.from(item.json.body, 'utf8');
else raw = Buffer.from(JSON.stringify(item.json.body ?? {}), 'utf8');

const headers = item.json.headers ?? {};
const provided = String(headers['x-bling-signature-256'] ?? headers['x-hub-signature-256'] ?? '')
  .trim()
  .replace(/^sha256=/i, '');

const safeEqual = (a, b) => {
  const ba = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  return ba.length === bb.length && crypto.timingSafeEqual(ba, bb);
};

let status;
if (!provided) {
  status = 'signature_unverified';        // o provider nao mandou assinatura
} else if (SECRETS.length === 0) {
  status = 'signature_unverified';        // nao ha segredo utilizavel configurado
} else {
  // O Bling documenta hex; aceitamos base64 tambem para nao depender do
  // formato exato do header, que e o unico elo que nao pudemos verificar.
  const ok = SECRETS.some((secret) => {
    const digest = crypto.createHmac('sha256', secret).update(raw).digest();
    return safeEqual(digest.toString('hex'), provided)
      || safeEqual(digest.toString('base64'), provided);
  });
  status = ok ? 'signature_valid' : 'discarded_invalid_signature';
}

const blocked = ENFORCE && status === 'discarded_invalid_signature';

return [{
  json: {
    ...item.json,
    signature_status: status,
    signature_enforced: ENFORCE,
    signature_secret_count: SECRETS.length,
    signature_blocked: blocked,
  },
  binary: item.binary,
}];

const crypto = require('crypto');
const item = $input.first();

let raw;
if (item.binary?.data) raw = await this.helpers.getBinaryDataBuffer(0, 'data');
else if (typeof item.json.rawBody === 'string') raw = Buffer.from(item.json.rawBody, 'utf8');
else if (typeof item.json.body === 'string') raw = Buffer.from(item.json.body, 'utf8');
else raw = Buffer.from(JSON.stringify(item.json.body ?? {}), 'utf8');

const rawBody = raw.toString('utf8');
let parsedPayload = null;
try { parsedPayload = JSON.parse(rawBody); } catch {}

const headers = item.json.headers ?? {};
const allow = ['content-type','user-agent','x-bling-signature-256','x-signature','x-shopee-signature','x-request-id','x-signature-version','x-signature-ts'];
const safeHeaders = {};
for (const key of allow) if (headers[key] !== undefined) safeHeaders[key] = String(headers[key]).slice(0, 2048);

const payload = parsedPayload ?? (typeof item.json.body === 'object' ? item.json.body : null);
const body = (payload && typeof payload.data === 'object' && payload.data !== null) ? payload.data : (payload ?? {});

// Identidade da ENTREGA, nao do recurso.
//
// `_id` identifica a notificacao; `resource` identifica o pedido e se repete a
// cada mudanca de estado dele. Usar `resource` aqui — como se fazia, porque o
// Mercado Livre nao manda `x-request-id` nem `id` e a cadeia caia no ultimo
// degrau — fazia toda notificacao seguinte sobre o mesmo pedido colidir na
// unique (source, dedupe_scope, dedupe_key). O RPC de aceite responde
// `should_process = false` nessa colisao: o evento e contado e descartado. Em
// 30 dias isso suprimiu 4.123 notificacoes do ML, contra 5 da Shopee e 0 do
// Bling, que mandam identificador proprio.
//
// Sem `_id`, o envelope fica sem id de entrega e o worker deduplica pelo hash
// do corpo — que difere entre notificacoes, porque `sent` difere. Falhar assim
// processa a mais, nunca a menos.
const deliveryId = headers['x-request-id'] ?? body._id ?? body.id ?? null;

// Identidade da CONTA. Esta e a unica que roteia.
//
// O `user_id` do corpo diz de quem e o evento, qualquer que tenha sido a porta
// de entrada. `application_id` diz por qual aplicativo a conta autorizou — a
// checagem cruzada de que a credencial que vamos usar e a certa.
const accountId = body.user_id ?? body.seller_id ?? null;

// Porta de entrada usada, e SO diagnostico.
//
// O Mercado Livre recusa a mesma URL de notificacao em dois aplicativos, entao
// cada conta entra por `/mercadolivre/<apelido>`. O apelido NAO decide nada:
// se algum dia ele nao bater com a conta que o `user_id` indica, isso aparece
// aqui como divergencia — sem desviar o evento para a conta errada.
const routeHint = item.json.params?.conta ?? item.json.query?.conta ?? null;

return [{ json: {
  schema_version: 1,
  event_id: crypto.randomUUID(),
  source: 'mercadolivre',
  received_at: new Date().toISOString(),
  headers: safeHeaders,
  raw_body: rawBody,
  parsed_payload: payload,
  body_sha256: crypto.createHash('sha256').update(raw).digest('hex'),
  provider_delivery_id: deliveryId === null || deliveryId === undefined ? null : String(deliveryId),
  account_id: accountId === null || accountId === undefined ? null : String(accountId),
  application_id: body.application_id === null || body.application_id === undefined ? null : String(body.application_id),
  provider_topic: body.topic ? String(body.topic).toLowerCase() : null,
  route_hint: routeHint === null || routeHint === undefined ? null : String(routeHint),
  payload_size: raw.length,
  oversized: raw.length > 1048576,
} }];

const envelope = $('Build Durable Envelope').first().json;
const data = Buffer.from(JSON.stringify(envelope), 'utf8');
return [{ json: envelope, binary: { data: { data: data.toString('base64'), mimeType: 'application/json', fileName: envelope.event_id + '.json' } } }];

// O Mercado Livre nao assina os webhooks. A unica garantia de origem e a
// faixa de IPs que eles publicam, entao a checagem acontece na borda, antes
// de qualquer persistencia.
//
// Qual IP e confiavel: o proxy reverso na frente do n8n ACRESCENTA o peer
// real ao final de X-Forwarded-For. O primeiro item da lista e o que o
// cliente enviou e portanto pode ser forjado. Usamos X-Real-IP quando
// existir (o proxy o define com $remote_addr) e, na falta dele, o ULTIMO
// item de X-Forwarded-For. Se houver mais de um proxy na cadeia, este
// calculo precisa ser revisto.
const ALLOWED = new Set([
  '54.88.218.97',
  '18.215.140.160',
  '18.213.114.129',
  '18.206.34.84',
  '35.236.253.169',
  '35.245.91.34',
  '35.245.20.104',
  '35.186.182.146',
]);

const item = $input.first();
const headers = item.json.headers ?? {};
const norm = (value) => String(value ?? '').trim().replace(/^::ffff:/i, '');

const forwarded = norm(headers['x-forwarded-for']).split(',').map(norm).filter(Boolean);
const realIp = norm(headers['x-real-ip']);
const peerIp = realIp || (forwarded.length ? forwarded[forwarded.length - 1] : '');
const allowed = Boolean(peerIp) && ALLOWED.has(peerIp);

return [{
  json: { ...item.json, client_ip: peerIp || null, ip_allowed: allowed },
  binary: item.binary,
}];

