const envelope = $('Build Durable Envelope').first().json;
const data = Buffer.from(JSON.stringify(envelope), 'utf8');
return [{ json: envelope, binary: { data: { data: data.toString('base64'), mimeType: 'application/json', fileName: envelope.event_id + '.json' } } }];

const crypto = require('crypto');
const webhook = $('Shopee Webhook').first().json;
const envelope = $('Build Durable Envelope').first().json;
const provided = String(webhook.headers?.authorization ?? '').trim();
const partnerKey = String($env.SHOPEE_PUSH_PARTNER_KEY ?? $env.SHOPEE_PARTNER_KEY ?? '').trim();
const configuredCallback = String($env.SHOPEE_CALLBACK_URL ?? '').trim();
const observedCallback = String(webhook.webhookUrl ?? '').trim();
const enforceInvalid = String($env.SHOPEE_SIGNATURE_ENFORCEMENT ?? 'audit').trim().toLowerCase() === 'required';
const candidates = [];
if (configuredCallback) candidates.push({ strategy: 'configured_callback', url: configuredCallback });
if (observedCallback && observedCallback !== configuredCallback) candidates.push({ strategy: 'observed_callback', url: observedCallback });
let status = 'signature_unverified';
let strategy = null;
let reason = 'missing_signature_material';
const validShape = /^[a-f0-9]{64}$/i.test(provided);
if (validShape && partnerKey && candidates.length && envelope.raw_body) {
  reason = 'hmac_mismatch';
  for (const candidate of candidates) {
    const calculated = crypto.createHmac('sha256', partnerKey).update(candidate.url + '|' + envelope.raw_body, 'utf8').digest('hex');
    if (crypto.timingSafeEqual(Buffer.from(calculated, 'hex'), Buffer.from(provided, 'hex'))) {
      status = 'signature_valid';
      strategy = candidate.strategy;
      reason = 'matched';
      break;
    }
  }
  if (status !== 'signature_valid' && enforceInvalid) status = 'discarded_invalid_signature';
}
return [{ json: { event_id: envelope.event_id, signature_status: status, signature_strategy: strategy, signature_reason: reason, signature_enforcement: enforceInvalid ? 'required' : 'audit', checked_at: new Date().toISOString() } }];
